import assert from 'node:assert/strict';
import { readFile } from 'node:fs/promises';
import path from 'node:path';
const directory=process.cwd();
    const { createUser, authenticate } = await import('../../server/auth');
    const input = { fullName: 'همسفر آزمایشی', phone: '09121234567', email: 'HELLO@example.com', password: '  Friendly1234  ' };
    const user = await createUser(input);
    assert.equal(user.email, 'hello@example.com');
    assert.equal(user.role, 'user');
    assert.equal('passwordHash' in user, false);
    const publicUser = JSON.parse(JSON.stringify(user));
    assert.deepEqual(await authenticate(' HELLO@EXAMPLE.COM ', input.password), publicUser);
    assert.deepEqual(await authenticate(input.phone, input.password), publicUser);
    assert.equal(await authenticate(input.phone, input.password.trim()), null);
    assert.equal(await authenticate('unknown@example.com', input.password), null);
    await assert.rejects(createUser(input), /ACCOUNT_EXISTS/);
    await assert.rejects(createUser({ ...input, email: 'other@example.com' }), /ACCOUNT_EXISTS/);
    await assert.rejects(createUser({ ...input, phone: '09121234568' }), /ACCOUNT_EXISTS/);
    const saved = JSON.parse(await readFile(path.join(directory, 'data', 'users.json'), 'utf8'));
    assert.equal(saved.length, 1);
    assert.equal('password' in saved[0], false);
    assert.ok(saved[0].passwordHash && saved[0].passwordSalt);
    assert.equal(JSON.stringify(saved).includes(input.password), false);
    const { readAdminDatabase, adminSnapshot } = await import('../../server/adminStore');
    const database = await readAdminDatabase();
    for (const resource of ['tours', 'bookings', 'products', 'customers', 'content', 'tickets'] as const) assert.deepEqual(database[resource], [], resource);
    const snapshot = await adminSnapshot();
    assert.ok(Object.values(snapshot.metrics).every(value => value === 0), 'a fresh installation must not create sample sales, profiles or trips');

const {closeBookingDatabase}=await import('../../server/bookingDb');closeBookingDatabase();
